import{z as l,x as s,o as E,c as p,q as A,j as o,D as t,d as n,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"多代理编排","description":"","frontmatter":{"title":"多代理编排","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multi-agent-orchestration.md","filePath":"llm/multi-agent-orchestration.md","lastUpdated":1791413859000}'),d={name:"llm/multi-agent-orchestration.md"};function m(u,a,h,g,D,C){const r=s("Mermaid");return E(),p("div",null,[a[2]||(a[2]=A('<h1 id="多代理编排" tabindex="-1">多代理编排 <a class="header-anchor" href="#多代理编排" aria-label="Permalink to &quot;多代理编排&quot;">​</a></h1><div class="epigraph"><p>把复杂任务拆成可对话的角色：每个代理有工具与人设，编排器决定谁在何时说话、消息如何写入共享状态，直到停机条件成立。</p><footer>—— 对照 Wu 等 AutoGen（arXiv:2308.08155）；Hong 等 MetaGPT（arXiv:2308.00352）；Li 等 CAMEL（arXiv:2303.17760）</footer></div><p>单代理工具循环（ReAct / function calling）把「选下一个动作」交给同一个上下文。任务一旦同时需要写代码、查文档、批评补丁、向人提问，单一提示会膨胀，角色污染，失败不可定位。<strong>多代理编排</strong>把这些职责拆成多个 LLM（或同一模型的多份提示），用对话、消息总线或工作流图来调度。它不是新的基座模型，而是控制面：谁持有哪些工具、共享什么记忆、如何终止。本篇写编排原语与评测该看什么。不把「多个代理」当成自动获得正确性的理由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAMEL（Li 等，arXiv:2303.17760）演示角色扮演：用户代理与助手代理靠 inception prompting 维持任务对齐的对话，用于生成合作轨迹、观察交际行为。固定两人、弱工具，适合研究对话动力学，不适合当通用运行时。MetaGPT（Hong 等，arXiv:2308.00352）把软件工程 SOP 写进提示：产品经理、架构师、工程师、评审按流水线交工件，口号是「代码 = SOP(团队)」。结构强、跑题少，换到非软件任务要重写 SOP。AutoGen（Wu 等，arXiv:2308.08155）把代理做成可对话、可定制的行动者：可用 LLM、人、工具的任意组合回复，用代码或自然语言定义对话模式（二人、群聊、嵌套），作为通用基础设施而不是单一 SOP。</p><p>编排要解决的具体失败是：无终止的互相吹捧、两个代理改同一文件、工具权限漏到不该持有的角色、以及把群聊全文每轮塞给所有人导致费用平方涨。评测若只报「最终答案对不对」，会藏过这些过程失败。需要把<strong>对话轮数、工具调用次数、人工介入次数、是否违反角色权限</strong>写成一等指标，再谈任务分数。</p><p><span class="marginnote">初学者容易以为「多代理 = 更聪明」。实际上多代理只是把同一个（或几份相同的）模型切成不同视角；没有单代理同模型对照的评测里，多出来的分数可能只是采样次数变多（Best-of-N）的功劳。</span></p><h3 id="三种常见拓扑" tabindex="-1">三种常见拓扑 <a class="header-anchor" href="#三种常见拓扑" aria-label="Permalink to &quot;三种常见拓扑&quot;">​</a></h3><p><strong>流水线</strong>：A 的输出是 B 的唯一输入，如 MetaGPT 的 SOP 链。易审计，不能回头，除非显式加评审环。<strong>对话图</strong>：谁回复谁由下一说话人策略决定，AutoGen 的群聊属于此类；动态但难保证公平与终止。<strong>层次</strong>：规划者拆子任务，执行者只看见子目标，结果汇总后再计划。层次清晰，规划者成为单点幻觉源。真实系统常混合：外层图、内层二人对话。不要把 CrewAI、LangGraph、ChatDev 的产品名当成新的数学对象——它们是这些拓扑上的工程封装。</p>',9)),(E(),o(i,null,{default:t(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SG1%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%EF%BC%9A%E5%8D%95%E5%90%91%E4%B8%8D%E5%9B%9E%E5%A4%B4%22%5D%0A%20%20%20%20A1%5B%22%E9%9C%80%E6%B1%82%22%5D%20--%3E%20A2%5B%22%E6%9E%B6%E6%9E%84%22%5D%20--%3E%20A3%5B%22%E7%BC%96%E7%A0%81%22%5D%0A%20%20end%0A%20%20subgraph%20SG2%5B%22%E5%AF%B9%E8%AF%9D%E5%9B%BE%EF%BC%9A%E7%AD%96%E7%95%A5%E5%AE%9A%E4%B8%8B%E4%B8%80%E8%AF%B4%E8%AF%9D%E4%BA%BA%22%5D%0A%20%20%20%20B1%5B%22%E5%85%B1%E4%BA%AB%E7%BE%A4%E8%81%8A%E6%97%A5%E5%BF%97%22%5D%20--%3E%20B2%5B%22%E4%B8%8B%E4%B8%80%E8%AF%B4%E8%AF%9D%E4%BA%BA%E7%AD%96%E7%95%A5%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E4%BB%BB%E4%B8%80%E4%BB%A3%E7%90%86%E5%8F%91%E8%A8%80%22%5D%20--%3E%20B1%0A%20%20end%0A%20%20subgraph%20SG3%5B%22%E5%B1%82%E6%AC%A1%EF%BC%9A%E8%A7%84%E5%88%92%E8%80%85%E5%B1%85%E4%B8%AD%22%5D%0A%20%20%20%20C1%5B%22%E8%A7%84%E5%88%92%E8%80%85%E6%8B%86%E5%AD%90%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20C2%5B%22%E6%89%A7%E8%A1%8C%E8%80%85%E5%8F%AA%E8%A7%81%E5%AD%90%E7%9B%AE%E6%A0%87%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22%E6%B1%87%E6%80%BB%E5%9B%9E%E8%A7%84%E5%88%92%E8%80%85%22%5D%20--%3E%20C1%0A%20%20end%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"Guo 等人的综述（arXiv:2402.01680）把 AutoGen、MetaGPT、CAMEL 并列为早期开源框架。写相关工作时引用原论文，不要用综述的转述数字替代原表。")],-1)),a[4]||(a[4]=e("h2",{id:"方法",tabindex:"-1"},[n("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[5]||(a[5]=e("p",null,"最小编排状态包括：代理注册表（人设、工具子集、模型名）、消息日志、共享工件（文件、票、数据库行）、终止谓词（最大轮数、任务完成标记、人 Stop）。每步：调度器选下一个说话者 → 该代理消费允许看见的切片 → 产出消息或工具调用 → 宿主执行工具 → 观察写回日志。人可以是一种特殊代理（AutoGen 强调 LLM / 人 / 工具混合模式），这比「全自动」更接近可上线系统。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"「终止谓词」翻译成大白话就是一段写给程序的条件判断：最大轮数到没到、完成标记有没有置位、人有没有喊停。少了它，最经典的事故是两个代理互相恭维到天亮，费用按 token 结算。")],-1)),a[7]||(a[7]=e("p",null,"评测协议应按任务家族分开。软件工程：同一仓库、同一隐藏测试、限制是否共享测试日志，对照单代理 SWE-agent / OpenHands，看多代理是否真的提高 resolved，还是只提高 token。数学与编码竞赛：AutoGen 论文用示例应用说明框架能力，那是案例，不是 SWE-bench。角色扮演数据生成：CAMEL 看对话是否维持角色与任务，而不是下游准确率。全局问答：多代理检索—写作—批评，要报是否比单次 RAG 在事实性上更好，而不是只报更长。任何「多代理赢」必须有单代理、同模型、同工具的对照，否则多出来的只是更多采样。",-1)),(E(),o(i,null,{default:t(()=>[B(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%20%2B%20%E5%85%B1%E4%BA%AB%E7%8A%B6%E6%80%81%22%5D%20--%3E%20S%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E9%80%89%E4%B8%8B%E4%B8%80%E8%AF%B4%E8%AF%9D%E8%80%85%22%5D%0A%20%20S%20--%3E%20A%5B%22%E4%BB%A3%E7%90%86%20i%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%88%87%E7%89%87%22%5D%0A%20%20A%20--%3E%20M%5B%22%E6%B6%88%E6%81%AF%E6%88%96%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%22%5D%0A%20%20M%20--%3E%20R%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%EF%BC%9A%E5%B7%A5%E5%85%B7%20%2F%20%E4%BA%BA%22%5D%0A%20%20R%20--%3E%20L%5B%22%E6%97%A5%E5%BF%97%E4%B8%8E%E5%B7%A5%E4%BB%B6%22%5D%0A%20%20L%20--%3E%20D%7B%22%E7%BB%88%E6%AD%A2%3F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20S%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20O%5B%22%E4%BA%A4%E4%BB%98%E7%89%A9%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<h3 id="对话编程相对静态图" tabindex="-1">对话编程相对静态图 <a class="header-anchor" href="#对话编程相对静态图" aria-label="Permalink to &quot;对话编程相对静态图&quot;">​</a></h3><p>AutoGen 把「对话模式」当成可组合原语：二人聊天、群聊、嵌套聊天可以拼进更大应用。静态图（后来的 LangGraph 一类）把边写死，可复现性强，改流程要改图。SOP（MetaGPT）是领域特化的静态图，节点是角色。选型等于选失败：动态对话会循环恭维；静态图会在未建模的异常处卡死。工程上常动态对话外包一层最大轮数与「批评者必须引用工件 diff」，把 SOP 的硬约束嵌进图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多代理并不增加模型的参数，它改变的是<strong>条件化上下文的分区</strong>。每个角色只看见与职责相关的工具说明和近期消息，降低指令冲突。批评者角色把「找错」写成目标，比同一模型在同一提示里既生成又自检更不容易自我开脱——这是角色提示的归纳偏置，不是定理。共享黑板（文件、票据）让通信走工件而非口头转述，减少电话游戏。心跳与超时防止死锁。</p><p>机制失败：角色漂移（工程师开始改需求）；权限泄漏（检索代理拿到写生产库的工具）；上下文爆炸（群聊每轮全量广播）；共谋式幻觉（两人互相确认错误事实）。缓解是工具 ACL、消息路由（只广播摘要）、以及把关键状态放进结构化票而不是散文。记忆若跨代理共享，要有写入者身份，否则 A 的错误笔记会变成 B 的前提；这与 <a href="/llm/memgpt">MemGPT</a> 的分层记忆、<a href="/llm/amem-agent-memory">A-MEM</a> 的笔记链接是不同层——编排解决谁说话，记忆解决说完后什么被保存。</p><p><span class="marginnote">共谋式幻觉可以类比「电话游戏」：一句话经几个人转述会走样，但更危险的是两个转述者互相点头确认走样的版本。所以关键状态要落成结构化票据（diff、命令、票号），让下一个角色读原文，而不是听转述。</span></p><p><span class="marginnote">费用模型近似为 \\(\\sum_i\\) 轮次\\(_i\\) \\(\\times\\) 上下文\\(_i\\)。群聊若不做摘要，上下文随轮数线性涨、总费用超线性。报多代理收益时必须报 token 倍数，否则不可与单代理 Best-of-N 比较。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="编排不能替代工具正确性" tabindex="-1">编排不能替代工具正确性 <a class="header-anchor" href="#编排不能替代工具正确性" aria-label="Permalink to &quot;编排不能替代工具正确性&quot;">​</a></h3><p>浏览器、shell、数据库工具的安全边界仍在宿主，见 <a href="/llm/openhands">OpenHands</a> 与 GUI 代理文。多代理只会让越权路径更难审计：一次「内部消息」可能触发另一个角色的危险工具。默认最小权限：每个代理一张白名单。不要为了「更像团队」给所有人同一把钥匙。</p><p>评测污染：用同一教师模型既当生成者又当自动评委，多代理的冗长答案容易赢「全面性」而输事实。应用 LLM-as-judge 时要固定评委模型、盲序、以及与任务相关的标准（正确性优先于文采）。MetaGPT 的 SOP 对软件演示强，不自动迁移到客服。CAMEL 的 inception prompting 是研究装置，生产里要用显式终止与人审替代「希望他们一直合作」。需要单代理工具循环时读 <a href="/llm/react">ReAct</a>；需要 IDE 里的人在环时读 <a href="/llm/agentic-coding">代理编码</a>。</p><p><span class="marginnote">出处：Wu et al.，<em>AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation</em>，arXiv:2308.08155；Hong et al.，<em>MetaGPT</em>，arXiv:2308.00352；Li et al.，<em>CAMEL</em>，arXiv:2303.17760。综述：Guo et al.，arXiv:2402.01680。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多代理编排是控制面：角色、工具 ACL、调度、共享工件与终止条件。</li><li>CAMEL 研究角色对话；MetaGPT 把 SOP 流水线化；AutoGen 提供可组合对话运行时。</li><li>评测必须有同模型单代理对照，并报告轮数、token 与权限违规。</li><li>拓扑选流水线、对话图或层次，等于选卡死方式与费用形状。</li><li>出处：Wu et al. arXiv:2308.08155；Hong et al. arXiv:2308.00352；Li et al. arXiv:2303.17760。</li></ul>',14))])}const P=l(d,[["render",m]]);export{c as __pageData,P as default};
